<script setup>
import {computed,ref} from 'vue'
import {useRoute,useRouter} from 'vue-router'
import {useIrrigation} from '../../data/runtime.js'
import {effectiveDeviceConnection} from '../../data/queries.js'
import {useClock} from '../../composables/useClock.js'
import {notify} from '../../composables/feedback.js'
import DataTable from '../../components/DataTable.vue'
import Pagination from '../../components/Pagination.vue'
import StatusBadge from '../../components/StatusBadge.vue'
import ResourceForm from '../fields/ResourceForm.vue'
import {latest,shortStamp,stamp,options,clone,readingNumber,readingFacts} from '../fields/resourceUi.js'
const r=useIrrigation(),route=useRoute(),router=useRouter(),clock=useClock(),tab=ref('mapping'),pointPage=ref(1),calibrationPage=ref(1),editing=ref(null),verifyBusy=ref(false),verificationError=ref('')
const e=computed(()=>r.state.entities),device=computed(()=>e.value.Device?.find(d=>d.deviceId===route.params.id)),points=computed(()=>e.value.Point?.filter(p=>p.deviceId===device.value?.deviceId)??[]),connection=computed(()=>device.value?effectiveDeviceConnection(device.value,clock.displayNow.value):'UNKNOWN'),calibrations=computed(()=>e.value.Calibration?.filter(c=>points.value.some(p=>p.pointId===c.pointId)).sort((a,b)=>Date.parse(b.calibratedAt)-Date.parse(a.calibratedAt))??[]),pointRows=computed(()=>points.value.map(p=>({...p,latest:latest(e.value.TelemetryReading??[],p.pointId)})))
const capabilities=[['read','读取'],['control','远程控制'],['feedback','动作反馈'],['localSchedule','本地调度']]
const columns=[{key:'index',label:'序号',width:90},{key:'pointId',label:'点位编号'},{key:'depthCm',label:'深度cm'},{key:'unit',label:'单位'},{key:'latest',label:'最新值'},{key:'observedAt',label:'采集时间'},{key:'quality',label:'质量'}]
const calColumns=[{key:'calibrationId',label:'校准编号'},{key:'pointId',label:'点位编号'},{key:'referenceValue',label:'参考值'},{key:'measuredValue',label:'实测值'},{key:'oldOffset',label:'原偏移'},{key:'newOffset',label:'新偏移'},{key:'actorId',label:'操作人'},{key:'calibratedAt',label:'校准时间'}]
async function verify(){verifyBusy.value=true;verificationError.value='';try{await r.commit('DEVICE_VERIFY',{deviceId:device.value.deviceId},{expectedVersion:device.value.version,clientRequestId:crypto.randomUUID()});notify('核验完成')}catch(e){verificationError.value=e.message}finally{verifyBusy.value=false}}
function editPoint(p){const {latest:reading,...pointFacts}=p;editing.value={title:'点位映射配置',action:'POINT_UPDATE',readOnly:!r.can('POINT_UPDATE',p),record:clone(pointFacts),fields:[{key:'pointId',label:'点位编号',readonly:true},{key:'name',label:'点位名称'},{key:'kind',label:'类型',options:[...new Set((e.value.Point??[]).map(p=>p.kind))].map(value=>({value,label:value}))},{key:'address',label:'同设备地址'},{key:'unit',label:'单位'},{key:'zoneId',label:'关联分区',options:options(e.value.IrrigationZone??[],'zoneId')},...['depthCm','rangeMin','rangeMax','scale','offset','staleAfterSec'].map((key,i)=>({key,label:['深度（cm）','量程下限','量程上限','比例系数','偏移量','有效期（秒）'][i],type:'number'}))]}}
const calPointId=ref('')
function calibrate(){const p=points.value.find(p=>p.pointId===calPointId.value)??points.value[0];if(!p)return;editing.value={title:'点位校准',action:'POINT_CALIBRATE',record:{pointId:p.pointId,version:p.version,referenceValue:null,measuredValue:null,note:''},fields:[{key:'pointId',label:'点位编号',readonly:true},{key:'referenceValue',label:'参考值',type:'number'},{key:'measuredValue',label:'现场实测值',type:'number'},{key:'note',label:'现场依据',type:'textarea'}]}}
function pointMonitor(){const p=editing.value.record,rd=latest(e.value.TelemetryReading??[],p.pointId);router.push({path:'/monitor',query:{pointId:p.pointId,zoneId:p.zoneId,date:rd?.observedAt.slice(0,10)}})}
function freshness(p){return readingFacts(latest(e.value.TelemetryReading??[],p.pointId),p,device.value,clock.displayNow.value)||'读数有效'}
</script>
<template><div v-if="device" class="page-stack device-detail"><div class="back-row"><button class="btn" @click="router.push('/devices')">〈　返回</button><span>设备编号：<strong>{{device.code}}</strong></span><button class="btn btn-primary" :disabled="verifyBusy||!r.can('DEVICE_VERIFY',device)" @click="verify">核验接入</button></div><p v-if="verificationError" class="inline-error" role="alert">{{verificationError}}</p><section class="panel device-overview"><div class="device-portrait"><svg viewBox="0 0 130 160" aria-label="设备外观示意" role="img"><defs><linearGradient id="probe-metal"><stop stop-color="#dce2e5"/><stop offset=".5" stop-color="#f9fafb"/><stop offset="1" stop-color="#bac3c8"/></linearGradient></defs><rect x="47" y="15" width="36" height="88" rx="16" fill="url(#probe-metal)" stroke="#e1e6e9"/><path d="M47 43h36" stroke="#16865c" stroke-width="5"/><path d="M55 102v39m10-39v39m10-39v39" stroke="#92999e" stroke-width="2"/><path d="M56 102v37m10-37v37m10-37v37" stroke="white"/></svg></div><div class="device-facts"><h2>{{device.name}}</h2><div class="device-badges"><StatusBadge :status="connection"/><StatusBadge :status="device.verification"/></div><div class="device-fact-columns"><dl class="data-pairs"><dt>设备编号</dt><dd>{{device.code}}</dd><dt>设备型号</dt><dd>{{device.model}}</dd><dt>生产厂家</dt><dd>{{device.manufacturer}}</dd></dl><dl class="data-pairs"><dt>版本号</dt><dd>{{device.version}}</dd><dt>点位数量</dt><dd>{{points.length}}</dd><dt>校准记录</dt><dd>{{calibrations.length}}</dd></dl></div></div><div class="capability-matrix"><h3 class="panel-title">能力矩阵</h3><div class="capability-grid"><div v-for="[key,label] in capabilities" :key="key"><span>{{label}}</span><StatusBadge :status="device.capabilities?.[key]?'ENABLED':'UNVERIFIED'" :text="device.capabilities?.[key]?'支持':'不支持'"/></div></div></div></section><section class="panel device-tabs"><div class="tabs" role="tablist"><button v-for="[key,label] in [['mapping','点位映射'],['calibration','校准记录'],['diagnostics','诊断']]" :key="key" class="tab" :class="{active:tab===key}" role="tab" :aria-selected="tab===key" @click="tab=key">{{label}}</button></div><template v-if="tab==='mapping'"><DataTable :columns="columns" :rows="pointRows.slice((pointPage-1)*15,pointPage*15)" row-key="pointId" compact @row-click="editPoint"><template #cell-index="{index}">{{(pointPage-1)*15+index+1}}</template><template #cell-pointId="{row}"><button class="btn-plain" @click.stop="editPoint(row)">{{row.pointId}}</button></template><template #cell-latest="{value}">{{readingNumber(value?.value)}}</template><template #cell-observedAt="{row}">{{shortStamp(row.latest?.observedAt)}}</template><template #cell-quality="{row}"><StatusBadge v-if="row.latest" :status="row.latest.quality"/><span v-else>无读数</span><small v-if="row.latest&&freshness(row)!=='读数有效'" class="point-facts warning-text">{{freshness(row)}}</small></template></DataTable><Pagination v-model="pointPage" :total="points.length"><template #summary>点位共{{points.length}}条，15条/页</template></Pagination></template><template v-else-if="tab==='calibration'"><div class="calibration-toolbar"><label>选择点位<select v-model="calPointId"><option value="">{{points[0]?.pointId??'暂无点位'}}</option><option v-for="p in points" :key="p.pointId" :value="p.pointId">{{p.pointId}}</option></select></label><button class="btn btn-primary" :disabled="!points.length||!r.can('POINT_CALIBRATE',points.find(p=>p.pointId===calPointId)||points[0])" @click="calibrate">校准</button></div><DataTable :columns="calColumns" :rows="calibrations.slice((calibrationPage-1)*15,calibrationPage*15)" row-key="calibrationId" compact><template #cell-actorId="{value}">{{e.User?.find(u=>u.userId===value)?.name??'—'}}</template><template #cell-calibratedAt="{value}">{{stamp(value)}}</template></DataTable><Pagination v-model="calibrationPage" :total="calibrations.length"/></template><template v-else><div class="diagnostic-summary"><dl class="data-pairs"><dt>连接状态</dt><dd><StatusBadge :status="connection"/></dd><dt>末次心跳</dt><dd>{{stamp(device.lastSeenAt)}}</dd><dt>接入核验</dt><dd><StatusBadge :status="device.verification"/></dd><dt>诊断结果</dt><dd>尚未配置可用的设备接入适配器，无法进行现场通信诊断。</dd></dl></div><DataTable :columns="[{key:'pointId',label:'点位编号'},{key:'observedAt',label:'最新采集时间'},{key:'freshness',label:'读数新鲜度'}]" :rows="pointRows" row-key="pointId" compact><template #cell-observedAt="{row}">{{stamp(row.latest?.observedAt)}}</template><template #cell-freshness="{row}">{{freshness(row)}}</template></DataTable></template></section><ResourceForm v-if="editing" :key="editing.action+editing.record.pointId" v-bind="editing" @close="editing=null"><template #default><button v-if="editing.action==='POINT_UPDATE'" type="button" class="btn-link" @click="pointMonitor">查看点位监测曲线 →</button></template></ResourceForm></div><div v-else class="panel empty-state">记录不存在 <button class="btn" @click="router.push('/devices')">返回设备列表</button></div></template>
<style scoped>.device-detail{gap:14px}.device-overview{display:flex;gap:15px;min-height:211px;padding:23px}.device-portrait{width:140px;height:163px;border:1px solid #edf0f2;background:#f8fafb;border-radius:7px;flex-shrink:0}.device-portrait svg{width:100%;height:100%}.device-facts{flex:1}.device-facts h2{font-size:23px;margin:0 0 9px}.device-badges{display:flex;gap:22px;margin-bottom:18px}.device-fact-columns{display:grid;grid-template-columns:1.35fr 1fr;gap:27px}.device-fact-columns dl+dl{border-left:1px solid #dce7e9;padding-left:30px}.device-fact-columns .data-pairs{gap:6px 24px;font-size:15px}.capability-matrix{width:39%;border-left:1px solid #e0e7e9;padding-left:33px}.capability-matrix .panel-title{margin-bottom:12px}.capability-grid{display:grid;grid-template-columns:1fr 1fr;gap:9px}.capability-grid>div{padding:12px 19px;border:1px solid #d7e2e5;border-radius:5px;display:flex;justify-content:space-between;align-items:center;gap:10px}.capability-grid :deep(.status-badge){min-width:77px}.device-tabs{padding:4px 23px 23px}.device-tabs .tabs{margin-bottom:13px}.device-tabs :deep(.data-table td){height:29.5px}.point-facts{display:block;font-size:11px;line-height:1.3}.device-tabs :deep(.status-badge){padding:0 10px;line-height:1.6}.device-tabs :deep(.pagination){margin-top:20px}.device-tabs :deep(.data-table){border:1px solid #dce6e9}.calibration-toolbar{display:flex;gap:20px;align-items:flex-end;margin:12px 0 18px}.calibration-toolbar label{display:flex;gap:15px;align-items:center}.calibration-toolbar select{width:260px}.diagnostic-summary{padding:15px 0 25px}@media(max-width:1200px){.device-overview{flex-wrap:wrap}.capability-matrix{width:100%;border:0;padding-left:0}.device-fact-columns{gap:10px}}
</style>
